-- Category of an ingredient (pasta, meats, vegetables, sauces, cheeses, breads, pizza_dough, salads, mixes); empty = none.
ALTER TABLE ingredients ADD COLUMN category TEXT;
UPDATE ingredients SET category = 'pasta' WHERE name IN ('Linguine', 'Spaghetti', 'Pennine', 'Cavatappi', 'Fusilli', 'Tortellini', 'Lasagne Bolognese', 'Lasagne Napolitaine');
UPDATE ingredients SET category = 'meats' WHERE name IN ('Poulet en lannières', 'Poulets en lanières', 'Bacon', 'Saumon', 'Saumon à déjeuner', 'Boulettes', 'Pepperoni', 'Capicollo', 'Capicollo en cubes', 'Jambon à pizza', 'Jambon effiloché', 'Saucisses', 'Bacon bits', 'Poulets Parmigiana', 'Poulets frits', 'Boules de poulet épicés', 'Ailes de poulet', 'Poissons', 'Crevettes 31/40');
UPDATE ingredients SET category = 'vegetables' WHERE name IN ('Brocoli', 'Champignons rôtis', 'Champignons', 'Oignons', 'Piments verts', 'Piments rouges', 'Tomates en cubes', 'Tomates séchées', 'Tomates en tranches', 'Olives vertes', 'Olives noires', 'Coeur d''artichaud', 'Oignons frits', 'Rondelles d''oignons', 'Frites', 'Frites épicées', 'Patates à déjeuner épicés', 'Patates à déjeuner sans épices', 'Citrons');
UPDATE ingredients SET category = 'sauces' WHERE name IN ('Sauce Alfredo', 'Sauce Carbonara', 'Sauce à Fruits de mer', 'Sauce fromage', 'Sauce Napolitaine', 'Sauce Bolognese', 'Sauce à pizza', 'Sauce Red Hot', 'Sauce BBQ Kansas City', 'Pesto', 'Bruchetta', 'Sauce Hollandaise', 'Sauce General Tao', 'Sauce à poutine', 'Vinaigrette Italienne', 'Vinaigrette Oignons doux', 'Vinaigrette Française', 'Vinaigrette Ranch', 'Vinaigrette Sud-Ouest', 'Vinaigrette Aioli', 'Vinaigrette César', 'Crème', 'Beurre à l''ail');
UPDATE ingredients SET category = 'cheeses' WHERE name IN ('Fromage Parmesan', 'Fromage Brie', 'Fromage Cantonier', 'Fromage Ficello', 'Fromage Mozarella', 'Fromage à sous-marin', 'Fromage Cheddar', 'Mélange 3 fromages', 'Faux fromage', 'Bâtonnets de fromage', 'Fromages à poutine');
UPDATE ingredients SET category = 'breads' WHERE name IN ('Pains à sous-marins 7 po', 'Pains à sous-marins 10 po', 'Croutons', 'Crêpes fines');
UPDATE ingredients SET category = 'pizza_dough' WHERE name IN ('Pâte à pizza 125g', 'Pâtes à pizza 250g', 'Pâtes à pizza 375g', 'Pâtes à pizza 500g');
UPDATE ingredients SET category = 'salads' WHERE name IN ('Salade Romaine', 'Salade Mesclun', 'Laitue', 'Concombres', 'Oignons rouges');
UPDATE ingredients SET category = 'mixes' WHERE name IN ('Mélange de fruits de mer', 'Mélange 3 viandes', 'Mélange à crêpes', 'Mélange à pains dorés');
